SELECT /* getValidCategoryCnt */
       COUNT(*)
  FROM TB_CODEXD DETAIL
 WHERE DETAIL.COMM_CODE = #{categoryCode}
   AND DETAIL.UPPR_CODE IS NOT NULL
   AND COALESCE(DETAIL.USEE_YSNO, #{commYes}) = #{commYes}
   AND DETAIL.COMD_CODE IN

    #{intrCode}

