/* setClub */
INSERT INTO TM_CLUBXM (
            OWNR_NUMB
          , CLUB_NAME
          , CLUB_CNTN
          , CLUB_VISB
          , JOIN_TYPE
          , CLUB_STAT
          , MAXX_MEMB
          , REGI_DATE
          , UPDT_DATE
) VALUES (  #{userNumb}
          , #{request.clubName}
          , #{request.clubCntn}
          , #{request.clubVisb}
          , #{request.joinType}
          , #{clubActive}
          , #{request.maxxMemb}
          , CURRENT_TIMESTAMP(6)
          , CURRENT_TIMESTAMP(6)
)

/* setClubCategory */
INSERT INTO TB_CLCATE (
            CLUB_NUMB
          , INTR_CODE
          , SORT_ORDR
          , REGI_DATE
) VALUES (  #{clubNumb}
          , #{intrCode}
          , #{sortOrdr}
          , CURRENT_TIMESTAMP(6)
)


/* setOwnerMember */
INSERT INTO TB_CLMEMX (
            CLUB_NUMB
          , USER_NUMB
          , MEMB_ROLE
          , MEMB_STAT
          , JOIN_DATE
          , BLOC_YSNO
          , REGI_DATE
          , UPDT_DATE
) VALUES (  #{clubNumb}
          , #{userNumb}
          , #{ownerRole}
          , #{memberActive}
          , CURRENT_TIMESTAMP(6)
          , #{commNo}
          , CURRENT_TIMESTAMP(6)
          , CURRENT_TIMESTAMP(6)
)

/* setClubQuestion */
INSERT INTO TB_CLQUES (
            CLUB_NUMB
          , QUES_FIRS
          , QUES_SECO
          , QUES_THIR
          , QUES_FOUR
          , QUES_FIFT
          , REGI_USER
          , REGI_DATE
          , UPDT_USER
          , UPDT_DATE
) VALUES (  #{question.clubNumb}
          , #{question.quesFirs,jdbcType=VARCHAR}
          , #{question.quesSeco,jdbcType=VARCHAR}
          , #{question.quesThir,jdbcType=VARCHAR}
          , #{question.quesFour,jdbcType=VARCHAR}
          , #{question.quesFift,jdbcType=VARCHAR}
          , #{userNumb}
          , CURRENT_TIMESTAMP(6)
          , #{userNumb}
          , CURRENT_TIMESTAMP(6)
)

