SELECT /* getClubDtl */
, MINE.MEMB_STAT , MINE.MEMB_ROLE , PENDING.JOIN_STAT FROM TM_CLUBXM CLUB LEFT JOIN TM_USERXM OWNER ON OWNER.USER_NUMB = CLUB.OWNR_NUMB
LEFT JOIN TB_CLMEMX MINE ON MINE.CLUB_NUMB = CLUB.CLUB_NUMB AND MINE.USER_NUMB = #{userNumb} LEFT JOIN TB_CLJOIN PENDING ON PENDING.CLUB_NUMB = CLUB.CLUB_NUMB AND PENDING.USER_NUMB = #{userNumb} AND PENDING.JOIN_STAT = #{applicationPending} WHERE CLUB.CLUB_NUMB = #{clubNumb}

