DELETE /* delExpiredInvitation */
  FROM TB_CLMEMX
 WHERE CLUB_NUMB = #{clubNumb}
   AND MEMB_STAT = #{memberInvited}
   AND EXPR_DATE <= CURRENT_TIMESTAMP(6)


DELETE /* delUserExpiredInvitation */
  FROM TB_CLMEMX
 WHERE USER_NUMB = #{userNumb}
   AND MEMB_STAT = #{memberInvited}
   AND EXPR_DATE <= CURRENT_TIMESTAMP(6)

