SELECT /* getOccupiedSeatCnt */
       COUNT(*)
  FROM TB_CLMEMX
 WHERE CLUB_NUMB = #{clubNumb}
   AND (
           MEMB_STAT = #{memberActive}
        OR (MEMB_STAT = #{memberInvited} AND EXPR_DATE > CURRENT_TIMESTAMP(6))
       )

