/* setActiveMember */
INSERT INTO TB_CLMEMX (
            CLUB_NUMB
          , USER_NUMB
          , MEMB_ROLE
          , MEMB_STAT
          , JOIN_DATE
          , BLOC_YSNO
          , REGI_DATE
          , UPDT_DATE
) VALUES (  #{clubNumb}
          , #{userNumb}
          , #{memberRole}
          , #{memberActive}
          , CURRENT_TIMESTAMP(6)
          , #{commNo}
          , CURRENT_TIMESTAMP(6)
          , CURRENT_TIMESTAMP(6)
