/* setInvitation */
INSERT INTO TB_CLMEMX (
            CLUB_NUMB
          , USER_NUMB
          , MEMB_ROLE
          , MEMB_STAT
          , SEND_NUMB
          , INVT_DATE
          , EXPR_DATE
          , BLOC_YSNO
          , REGI_DATE
          , UPDT_DATE
) VALUES (  #{clubNumb}
          , #{userNumb}
          , #{memberRole}
          , #{memberInvited}
          , #{senderNumb}
          , CURRENT_TIMESTAMP(6)
          , DATE_ADD(CURRENT_TIMESTAMP(6), INTERVAL 3 DAY)
          , #{commNo}
          , CURRENT_TIMESTAMP(6)
          , CURRENT_TIMESTAMP(6)
)

mapper.update:

UPDATE /* uptInvitationAccepted */
       TB_CLMEMX
   SET MEMB_STAT = #{memberActive}
     , SEND_NUMB = NULL
     , INVT_DATE = NULL
     , EXPR_DATE = NULL
     , JOIN_DATE = CURRENT_TIMESTAMP(6)
     , UPDT_DATE = CURRENT_TIMESTAMP(6)
 WHERE CLUB_NUMB = #{clubNumb}
   AND USER_NUMB = #{userNumb}
   AND MEMB_STAT = #{memberInvited}
   AND EXPR_DATE > CURRENT_TIMESTAMP(6)

